-- ============================================================================
-- Country Monkey: FLAG questions ("Whose flag is this?") -- 254 flags from
-- public/flags/ (the free flag-icons set; credit in public/flags/LICENSE).
--
-- Randy's call: all flags are fair game -- countries, territories, regional
-- flags (Scotland, Catalonia, ...) and organizations (EU, UN, ...). This is
-- learning as much as competition. Left out: 17 files that are just their
-- parent country's flag (e.g. the French territories fly the tricolor) or a
-- placeholder, since the right answer would be ambiguous.
--
-- A Country Monkey game mixes these in (about 3 of 15). Wrong answers are
-- look-alike FLAGS (picked by how the flags actually look -- Ireland gets Ivory
-- Coast and Italy, Poland gets Indonesia), never a near-identical twin (Chad
-- is never offered against Romania, nor Monaco against Indonesia).
-- accepted_answers: alternate names for the typed Final Wager.
--
-- category = region; 'WORLD' rows (UN, Antarctica, French Southern Lands)
-- only appear in World Wide games. Rows: Africa 60, Europe 61, Asia & Pacific 54, Middle East 26, Americas 50, World Wide only 3.
--
-- Safe to re-run: deletes and re-inserts the flag questions only (subcategory
-- 'FLAG'), in a transaction. Maps and water aren't touched.
-- ============================================================================

BEGIN;

ALTER TABLE questions ADD COLUMN IF NOT EXISTS wrong_answers TEXT[];
ALTER TABLE questions ADD COLUMN IF NOT EXISTS accepted_answers TEXT[];

DELETE FROM questions WHERE game_mode = 'COUNTRY_MONKEY' AND subcategory = 'FLAG';

INSERT INTO questions (question_number, game_mode, category, subcategory, faction, question_text, visual_asset, correct_answer, wrong_answers, accepted_answers, points)
SELECT (SELECT COALESCE(MAX(question_number), 0) FROM questions) + ROW_NUMBER() OVER (),
       'COUNTRY_MONKEY', v.region, 'FLAG', v.region, 'Whose flag is this?', v.visual_asset, v.correct_answer, v.wrong_answers, v.accepted_answers, v.points
FROM (VALUES
